using Servicio.RetazoMarket.Business.DTOs.Favorito;
namespace Servicio.RetazoMarket.Business.Validators;public static class FavoritoValidator {public static IReadOnlyCollection<string> Validar(AgregarFavoritoRequest r){var e=new List<string>();if(r is null)return ["La solicitud no puede ser nula."];if(r.id_cliente<=0)e.Add("El cliente es obligatorio.");if(r.id_producto<=0)e.Add("El producto es obligatorio.");return e;}public static IReadOnlyCollection<string> ValidarFiltro(FavoritoFiltroRequest r){var e=new List<string>();if(r is null)return ["El filtro no puede ser nulo."];if(r.id_cliente<=0)e.Add("El cliente es obligatorio.");if(!string.IsNullOrWhiteSpace(r.estado_producto)&&r.estado_producto.Trim().ToUpperInvariant() is not("ACT" or "INA"))e.Add("El estado debe ser ACT o INA.");if(r.page_number<=0)e.Add("El número de página debe ser mayor que cero.");if(r.page_size<=0||r.page_size>100)e.Add("El tamaño de página debe estar entre 1 y 100.");return e;}}
